+    private void stopTimer() {
+        // Stop the timer in a try/catch so that an IllegalStateException won't
+        // abort toolkit shutdown.
+        try {
+            pulseTimer.stop();
+        } catch (IllegalStateException ex) {
+            ex.printStackTrace();
+        }
+    }
